/* Version B: one pinned worker per node */
void *init(void *arg) {
    struct job *j = arg;   /* j->node, j->lo, j->hi */
    numa_run_on_node(j->node);
    for (size_t i = j->lo; i < j->hi; i++)
        a[i] = 1.0;        /* first write happens on j->node */
    return NULL;
