#include <numaif.h>      /* link with -lnuma */
#include <sys/mman.h>
#include <stdio.h>
#include <string.h>

size_t len = 1UL << 30;                        /* 1 GiB */
void *p = mmap(NULL, len, PROT_READ | PROT_WRITE,
               MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

unsigned long nodes = (1UL << 0) | (1UL << 1); /* nodes 0 and 1 */
/* VMA policy for this range only; install before first touch */
if (mbind(p, len, MPOL_INTERLEAVE, &nodes, 8 * sizeof nodes, 0) != 0)
    perror("mbind");

memset(p, 0, len);  /* faults pages in, alternating nodes 0 and 1 */
